import { useEffect, useRef } from "react";
import {
    DocumentEditorContainerComponent,
    Toolbar, Ribbon, Search
} from '@syncfusion/ej2-react-documenteditor';
import "./DocxEditor.css"
import DocxEditorSidePanel from "./DocxEditorSidePanel";

DocumentEditorContainerComponent.Inject(Toolbar, Ribbon, Search);

const DocxEditor = () => {
    const docxEditorRef = useRef<any>(null);

    const sfdt = {"sfdt":""}
    
    useEffect(() => {
        if (docxEditorRef.current) {
            docxEditorRef.current.documentEditor.open(sfdt);
        }
    }, []);

    return (
        <div className="docx-layout">
            <div className='docx-viewer-panel'>
                <DocumentEditorContainerComponent
                    id="container"
                    ref={docxEditorRef}
                    height="100%"
                    toolbarMode="Ribbon"
                    // Use the following service URL only for demo purposes
                    serviceUrl="https://document.syncfusion.com/web-services/docx-editor/api/documenteditor/"
                    enableToolbar={true}
                />
            </div>
            <DocxEditorSidePanel docxEditorRef={docxEditorRef} />
        </div>
    );
};

export default DocxEditor;